/**
 * Verifiable Evidence Bundle Contract (#1160)
 *
 * Implements the core domain schema, RFC 8785 canonical JSON serialization,
 * SHA-256 cryptographic hashing, Merkle root computation, append-only ledger rules,
 * clock-skew mitigation, duplicate detection, and untrusted input validation
 * for civic complaint evidence packages.
 *
 * Statutory Guardrail:
 * Mathematical verification proves data integrity and chronological provenance.
 * It does NOT constitute sovereign government verification or guaranteed legal redressal.
 */

export const BUNDLE_SCHEMA_VERSION = '1.0.0';

export const PROVENANCE_TIERS = {
  CITIZEN_ASSERTION: 'CITIZEN_ASSERTION',
  INDEPENDENT_VERIFICATION: 'INDEPENDENT_VERIFICATION',
  SYSTEM_OBSERVED: 'SYSTEM_OBSERVED',
};

export const PROVENANCE_TIER_LABELS = {
  CITIZEN_ASSERTION: 'Citizen Assertion (Unverified Claim)',
  INDEPENDENT_VERIFICATION: 'Independently Verified Record',
  SYSTEM_OBSERVED: 'System Observed Metadata',
};

export const PROVENANCE_TIER_DESCRIPTIONS = {
  CITIZEN_ASSERTION: 'Photographs, personal statements, and user logs collected by the citizen. Not independently attested by public authorities.',
  INDEPENDENT_VERIFICATION: 'Official statutory fee receipts, registered speed post tokens, departmental acknowledgement receipts (e.g. CPGRAMS, Jan Sunwai), and RTI replies.',
  SYSTEM_OBSERVED: 'Automated device timestamps, hash computation digests, and cryptographic verification logs generated by the client runtime.',
};

export const EVIDENCE_SOURCE_TYPES = {
  CITIZEN_PHOTO: 'CITIZEN_PHOTO',
  FEE_RECEIPT: 'FEE_RECEIPT',
  PORTAL_ACKNOWLEDGEMENT: 'PORTAL_ACKNOWLEDGEMENT',
  SPEED_POST_SLIP: 'SPEED_POST_SLIP',
  RTI_REPLY: 'RTI_REPLY',
  OFFICIAL_LETTER: 'OFFICIAL_LETTER',
  INSPECTION_NOTE: 'INSPECTION_NOTE',
  COMMUNICATION_LOG: 'COMMUNICATION_LOG',
  OTHER: 'OTHER',
};

export const EVIDENCE_SOURCE_LABELS = {
  CITIZEN_PHOTO: 'Incident Photograph / Video Capture',
  FEE_RECEIPT: 'Statutory Fee / Challan Receipt',
  PORTAL_ACKNOWLEDGEMENT: 'Official Portal Acknowledgement Slip',
  SPEED_POST_SLIP: 'Registered Speed Post Tracking Receipt',
  RTI_REPLY: 'Right to Information (RTI) Reply / Inspection Memo',
  OFFICIAL_LETTER: 'Departmental Written Notice or Correspondence',
  INSPECTION_NOTE: 'Site Inspection / Defect Verification Log',
  COMMUNICATION_LOG: 'Phone Call / Visit Summary Note',
  OTHER: 'Other Supporting Document',
};

export const INTEGRITY_STATUS = {
  VERIFIED: 'VERIFIED',
  TAMPERED: 'TAMPERED',
  BROKEN_CHAIN: 'BROKEN_CHAIN',
  CLOCK_SKEW_WARNING: 'CLOCK_SKEW_WARNING',
  INVALID_PAYLOAD: 'INVALID_PAYLOAD',
};

export const GENESIS_PREV_HASH = '0'.repeat(64);

export const BUNDLE_CONSTRAINTS = {
  MAX_ATTACHMENT_SIZE_BYTES: 5 * 1024 * 1024, // 5 MB per file
  MAX_BUNDLE_ENTRIES: 50,
  DEFAULT_CLOCK_SKEW_TOLERANCE_MS: 5 * 60 * 1000, // 5 minutes
  MAX_TITLE_LENGTH: 120,
  MAX_ANNOTATION_LENGTH: 2000,
  ALLOWED_MIME_TYPES: [
    'image/jpeg',
    'image/png',
    'image/webp',
    'application/pdf',
    'text/plain',
    'application/json',
  ],
};

export const STATUTORY_EVIDENCE_DISCLAIMER =
  'Civic Help Setu Verifiable Evidence Bundles establish mathematical data integrity, chronological provenance, and tamper detection for citizen records. This tool does NOT provide legal advice, official sovereign attestation, or guaranteed grievance resolution. To lodge a formal grievance, submit your records to official departmental channels.';

/**
 * Deterministic JSON Canonicalization (RFC 8785 compatible).
 * Sorts object keys lexicographically and strips all optional whitespace.
 *
 * @param {*} value
 * @returns {string} Canonical JSON string
 */
export function canonicalizeJson(value) {
  if (value === null || typeof value !== 'object') {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map((item) => canonicalizeJson(item)).join(',')}]`;
  }
  const keys = Object.keys(value).filter((k) => value[k] !== undefined).sort();
  const entries = keys.map((k) => `${JSON.stringify(k)}:${canonicalizeJson(value[k])}`);
  return `{${entries.join(',')}}`;
}

/**
 * Universal SHA-256 Digest computation (hex output).
 * Uses Web Crypto (subtle) if available, with Node.js crypto fallback.
 *
 * @param {string|Uint8Array|ArrayBuffer} data
 * @returns {Promise<string>} 64-character lowercase hex string
 */
export async function computeSha256Hex(data) {
  let uint8;
  if (typeof data === 'string') {
    uint8 = new TextEncoder().encode(data);
  } else if (data instanceof Uint8Array) {
    uint8 = data;
  } else if (data instanceof ArrayBuffer) {
    uint8 = new Uint8Array(data);
  } else if (typeof globalThis.Buffer !== 'undefined' && globalThis.Buffer.isBuffer(data)) {
    uint8 = new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
  } else {
    uint8 = new TextEncoder().encode(String(data || ''));
  }

  if (typeof globalThis !== 'undefined' && globalThis.crypto?.subtle?.digest) {
    const buffer = await globalThis.crypto.subtle.digest('SHA-256', uint8);
    const bytes = new Uint8Array(buffer);
    let hex = '';
    for (let i = 0; i < bytes.length; i++) {
      hex += bytes[i].toString(16).padStart(2, '0');
    }
    return hex;
  }

  try {
    const nodeCrypto = await import(/* @vite-ignore */ 'crypto');
    return nodeCrypto.createHash('sha256').update(uint8).digest('hex');
  } catch {
    throw new Error('No cryptographic SHA-256 engine available.');
  }
}

/**
 * Computes canonical SHA-256 entry hash.
 * Excludes dynamic client-computed runtime properties (like `entryHash` itself).
 *
 * @param {Object} entry
 * @returns {Promise<string>}
 */
export async function computeEntryHash(entry) {
  if (!entry || typeof entry !== 'object') {
    throw new Error('Cannot compute entry hash on invalid entry object.');
  }

  const payload = {
    sequence: Number(entry.sequence),
    entryId: String(entry.entryId),
    timestamp: String(entry.timestamp),
    source: String(entry.source),
    provenanceTier: String(entry.provenanceTier),
    title: String(entry.title || ''),
    userAnnotation: String(entry.userAnnotation || ''),
    attachment: entry.attachment
      ? {
          fileName: String(entry.attachment.fileName || ''),
          mimeType: String(entry.attachment.mimeType || ''),
          byteSize: Number(entry.attachment.byteSize || 0),
          sha256: String(entry.attachment.sha256 || ''),
        }
      : null,
    metadata: entry.metadata && typeof entry.metadata === 'object' ? entry.metadata : {},
    previousEntryHash: String(entry.previousEntryHash || GENESIS_PREV_HASH),
  };

  const canonical = canonicalizeJson(payload);
  return computeSha256Hex(canonical);
}

/**
 * Computes binary Merkle tree root over an array of 64-char SHA-256 hashes.
 *
 * @param {string[]} hashes
 * @returns {Promise<string>} Merkle root hash
 */
export async function computeMerkleRoot(hashes = []) {
  if (!Array.isArray(hashes) || hashes.length === 0) {
    return GENESIS_PREV_HASH;
  }
  if (hashes.length === 1) {
    return hashes[0];
  }

  let currentLevel = [...hashes];
  while (currentLevel.length > 1) {
    const nextLevel = [];
    for (let i = 0; i < currentLevel.length; i += 2) {
      const left = currentLevel[i];
      const right = i + 1 < currentLevel.length ? currentLevel[i + 1] : left;
      const combined = await computeSha256Hex(`${left}${right}`);
      nextLevel.push(combined);
    }
    currentLevel = nextLevel;
  }

  return currentLevel[0];
}

/**
 * Computes the canonical seal hash for the entire manifest header + chain state.
 *
 * @param {Object} manifest
 * @returns {Promise<string>}
 */
export async function computeManifestSeal(manifest) {
  if (!manifest || typeof manifest !== 'object') {
    throw new Error('Cannot compute seal on invalid manifest.');
  }

  const headerPayload = {
    schemaVersion: manifest.schemaVersion || BUNDLE_SCHEMA_VERSION,
    bundleId: manifest.bundleId,
    complaintId: manifest.complaintId,
    complaintTitle: manifest.complaintTitle,
    department: manifest.department,
    createdAt: manifest.createdAt,
    clockSkewToleranceMs: manifest.clockSkewToleranceMs || BUNDLE_CONSTRAINTS.DEFAULT_CLOCK_SKEW_TOLERANCE_MS,
    chainState: {
      entryCount: manifest.entries?.length || 0,
      rootHash: manifest.chainState?.rootHash || GENESIS_PREV_HASH,
      latestEntryHash: manifest.chainState?.latestEntryHash || GENESIS_PREV_HASH,
    },
  };

  return computeSha256Hex(canonicalizeJson(headerPayload));
}

/**
 * Validates an individual evidence entry payload.
 *
 * @param {Object} entry
 * @returns {{ isValid: boolean, errors: string[] }}
 */
export function validateBundleEntry(entry) {
  const errors = [];
  if (!entry || typeof entry !== 'object') {
    return { isValid: false, errors: ['Entry must be an object.'] };
  }

  if (typeof entry.sequence !== 'number' || entry.sequence < 1 || !Number.isInteger(entry.sequence)) {
    errors.push('Entry sequence must be a positive integer.');
  }
  if (!entry.entryId || typeof entry.entryId !== 'string' || !entry.entryId.trim()) {
    errors.push('Entry entryId is required.');
  }
  if (!entry.timestamp || isNaN(new Date(entry.timestamp).getTime())) {
    errors.push(`Entry timestamp is invalid or missing: "${entry.timestamp}".`);
  }
  if (!Object.values(PROVENANCE_TIERS).includes(entry.provenanceTier)) {
    errors.push(`Invalid provenanceTier: "${entry.provenanceTier}".`);
  }
  if (!Object.values(EVIDENCE_SOURCE_TYPES).includes(entry.source)) {
    errors.push(`Invalid evidence source: "${entry.source}".`);
  }
  if (!entry.title || typeof entry.title !== 'string' || entry.title.trim().length === 0) {
    errors.push('Entry title is required.');
  } else if (entry.title.length > BUNDLE_CONSTRAINTS.MAX_TITLE_LENGTH) {
    errors.push(`Entry title exceeds maximum length of ${BUNDLE_CONSTRAINTS.MAX_TITLE_LENGTH} characters.`);
  }

  if (entry.userAnnotation && entry.userAnnotation.length > BUNDLE_CONSTRAINTS.MAX_ANNOTATION_LENGTH) {
    errors.push(`User annotation exceeds maximum length of ${BUNDLE_CONSTRAINTS.MAX_ANNOTATION_LENGTH} characters.`);
  }

  if (entry.attachment) {
    const att = entry.attachment;
    if (!att.fileName || typeof att.fileName !== 'string') {
      errors.push('Attachment fileName is required.');
    }
    if (typeof att.byteSize !== 'number' || att.byteSize < 0) {
      errors.push('Attachment byteSize must be a non-negative number.');
    } else if (att.byteSize > BUNDLE_CONSTRAINTS.MAX_ATTACHMENT_SIZE_BYTES) {
      errors.push(`Attachment size (${att.byteSize} bytes) exceeds limit of ${BUNDLE_CONSTRAINTS.MAX_ATTACHMENT_SIZE_BYTES} bytes.`);
    }
    if (!att.sha256 || !/^[a-f0-9]{64}$/i.test(att.sha256)) {
      errors.push('Attachment sha256 must be a 64-character hex digest.');
    }
  }

  if (!entry.previousEntryHash || !/^[a-f0-9]{64}$/i.test(entry.previousEntryHash)) {
    errors.push('Entry previousEntryHash must be a 64-character hex digest.');
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
}

/**
 * Validates the structure and constraints of a complete bundle manifest.
 *
 * @param {Object} manifest
 * @returns {{ isValid: boolean, errors: string[] }}
 */
export function validateBundleManifest(manifest) {
  const errors = [];
  if (!manifest || typeof manifest !== 'object') {
    return { isValid: false, errors: ['Manifest must be a valid object.'] };
  }

  if (manifest.schemaVersion !== BUNDLE_SCHEMA_VERSION) {
    errors.push(`Unsupported schemaVersion "${manifest.schemaVersion}". Expected "${BUNDLE_SCHEMA_VERSION}".`);
  }
  if (!manifest.bundleId || typeof manifest.bundleId !== 'string') {
    errors.push('bundleId is required.');
  }
  if (!manifest.complaintId || typeof manifest.complaintId !== 'string') {
    errors.push('complaintId is required.');
  }
  if (!manifest.complaintTitle || typeof manifest.complaintTitle !== 'string') {
    errors.push('complaintTitle is required.');
  }
  if (!Array.isArray(manifest.entries)) {
    errors.push('Manifest entries must be an array.');
  } else if (manifest.entries.length > BUNDLE_CONSTRAINTS.MAX_BUNDLE_ENTRIES) {
    errors.push(`Bundle entries count (${manifest.entries.length}) exceeds maximum limit of ${BUNDLE_CONSTRAINTS.MAX_BUNDLE_ENTRIES}.`);
  } else {
    manifest.entries.forEach((entry, idx) => {
      const entryValidation = validateBundleEntry(entry);
      if (!entryValidation.isValid) {
        errors.push(`Entry #${idx + 1} validation failed: ${entryValidation.errors.join('; ')}`);
      }
    });
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
}

/**
 * Scans evidence entries for chronological anomalies and clock skew.
 *
 * @param {Array<Object>} entries
 * @param {Object} [options]
 * @param {number} [options.clockSkewToleranceMs]
 * @param {Date|string} [options.referenceTime]
 * @returns {Array<{ code: string, message: string, sequence: number, entryId: string, severity: string }>}
 */
export function detectClockSkew(entries = [], options = {}) {
  const warnings = [];
  if (!Array.isArray(entries) || entries.length === 0) return warnings;

  const tolerance = options.clockSkewToleranceMs || BUNDLE_CONSTRAINTS.DEFAULT_CLOCK_SKEW_TOLERANCE_MS;
  const now = options.referenceTime ? new Date(options.referenceTime).getTime() : Date.now();

  for (let i = 0; i < entries.length; i++) {
    const curr = entries[i];
    const currTime = new Date(curr.timestamp).getTime();

    // Check future-dating beyond tolerance
    if (currTime > now + tolerance) {
      warnings.push({
        code: 'FUTURE_TIMESTAMP_DETECTED',
        severity: 'WARNING',
        sequence: curr.sequence,
        entryId: curr.entryId,
        message: `Entry #${curr.sequence} timestamp (${curr.timestamp}) is in the future beyond allowed tolerance (${Math.round((currTime - now) / 1000)}s delta).`,
      });
    }

    // Check retrograde chronological ordering against preceding entry
    if (i > 0) {
      const prev = entries[i - 1];
      const prevTime = new Date(prev.timestamp).getTime();
      if (currTime < prevTime) {
        warnings.push({
          code: 'CHRONOLOGICAL_REGRESSION',
          severity: 'WARNING',
          sequence: curr.sequence,
          entryId: curr.entryId,
          message: `Entry #${curr.sequence} timestamp (${curr.timestamp}) occurs prior to preceding Entry #${prev.sequence} (${prev.timestamp}).`,
        });
      }
    }
  }

  return warnings;
}

/**
 * Scans evidence entries for duplicate attachments (matching SHA-256).
 *
 * @param {Array<Object>} entries
 * @returns {Array<{ code: string, entryId: string, sequence: number, duplicateOfEntryId: string, sha256: string }>}
 */
export function detectDuplicateEvidence(entries = []) {
  const duplicates = [];
  if (!Array.isArray(entries) || entries.length === 0) return duplicates;

  const seenHashes = new Map();

  for (const entry of entries) {
    if (entry.attachment?.sha256) {
      const hash = entry.attachment.sha256.toLowerCase();
      if (seenHashes.has(hash)) {
        const original = seenHashes.get(hash);
        duplicates.push({
          code: 'DUPLICATE_ATTACHMENT',
          sequence: entry.sequence,
          entryId: entry.entryId,
          duplicateOfSequence: original.sequence,
          duplicateOfEntryId: original.entryId,
          sha256: hash,
          fileName: entry.attachment.fileName,
        });
      } else {
        seenHashes.set(hash, { entryId: entry.entryId, sequence: entry.sequence });
      }
    }
  }

  return duplicates;
}

/**
 * End-to-end cryptographic and structural integrity verification of a bundle manifest.
 *
 * Checks:
 * 1. Structural schema validity.
 * 2. Monotonic sequence continuity (1, 2, 3...).
 * 3. Hash chain continuity (previousEntryHash links to previous entry's exact hash).
 * 4. Deterministic entry hash match against canonicalized payload.
 * 5. Optional raw file byte hash verification if files map provided.
 * 6. Merkle root tree re-computation and comparison.
 * 7. Manifest seal re-computation.
 * 8. Clock skew and duplicate detection warnings.
 *
 * @param {Object} manifest
 * @param {Object} [rawFiles] Map of entryId or sha256 to string/Uint8Array/Buffer
 * @param {Object} [options]
 * @returns {Promise<{ isValid: boolean, status: string, errors: string[], warnings: Object[], checkedEntriesCount: number, verifiedAt: string }>}
 */
export async function verifyBundleIntegrity(manifest, rawFiles = {}, options = {}) {
  const verifiedAt = new Date().toISOString();
  const errors = [];
  const warnings = [];

  const manifestCheck = validateBundleManifest(manifest);
  if (!manifestCheck.isValid) {
    return {
      isValid: false,
      status: INTEGRITY_STATUS.INVALID_PAYLOAD,
      errors: manifestCheck.errors,
      warnings: [],
      checkedEntriesCount: 0,
      verifiedAt,
    };
  }

  const entries = manifest.entries || [];
  const entryHashes = [];
  let expectedPrevHash = GENESIS_PREV_HASH;

  for (let i = 0; i < entries.length; i++) {
    const entry = entries[i];
    const expectedSeq = i + 1;

    // Check monotonic sequence
    if (entry.sequence !== expectedSeq) {
      errors.push(`Sequence mismatch at index ${i}: expected ${expectedSeq}, got ${entry.sequence}.`);
    }

    // Check previous hash linkage
    if (entry.previousEntryHash !== expectedPrevHash) {
      errors.push(`Chain broken at Entry #${entry.sequence} (${entry.entryId}): expected previousEntryHash "${expectedPrevHash}", got "${entry.previousEntryHash}".`);
    }

    // Recompute entry hash
    const computedHash = await computeEntryHash(entry);
    if (entry.entryHash !== computedHash) {
      errors.push(`Entry hash mismatch at Entry #${entry.sequence} (${entry.entryId}): stored "${entry.entryHash}", computed "${computedHash}".`);
    }

    // If raw file bytes provided for this entry, verify attachment sha256
    if (entry.attachment?.sha256) {
      const filePayload = rawFiles[entry.entryId] || rawFiles[entry.attachment.sha256];
      if (filePayload) {
        const computedFileHash = await computeSha256Hex(filePayload);
        if (computedFileHash.toLowerCase() !== entry.attachment.sha256.toLowerCase()) {
          errors.push(`Attachment byte corruption at Entry #${entry.sequence} (${entry.attachment.fileName}): manifest sha256 "${entry.attachment.sha256}", actual byte sha256 "${computedFileHash}".`);
        }
      }
    }

    entryHashes.push(entry.entryHash || computedHash);
    expectedPrevHash = entry.entryHash || computedHash;
  }

  // Merkle root verification
  const computedMerkleRoot = await computeMerkleRoot(entryHashes);
  if (manifest.chainState?.rootHash && manifest.chainState.rootHash !== computedMerkleRoot) {
    errors.push(`Merkle root mismatch: stored "${manifest.chainState.rootHash}", computed "${computedMerkleRoot}".`);
  }

  // Manifest seal verification
  if (manifest.chainState?.manifestSeal) {
    const expectedSeal = await computeManifestSeal({
      ...manifest,
      chainState: {
        ...manifest.chainState,
        rootHash: computedMerkleRoot,
        latestEntryHash: expectedPrevHash,
      },
    });
    if (manifest.chainState.manifestSeal !== expectedSeal) {
      errors.push(`Manifest seal mismatch: stored "${manifest.chainState.manifestSeal}", computed "${expectedSeal}".`);
    }
  }

  // Non-blocking diagnostic warnings
  const skewWarnings = detectClockSkew(entries, options);
  const dupWarnings = detectDuplicateEvidence(entries);
  warnings.push(...skewWarnings, ...dupWarnings);

  const isValid = errors.length === 0;
  let status = INTEGRITY_STATUS.VERIFIED;
  if (!isValid) {
    const hasChainError = errors.some((e) => e.includes('Chain broken') || e.includes('Sequence mismatch'));
    status = hasChainError ? INTEGRITY_STATUS.BROKEN_CHAIN : INTEGRITY_STATUS.TAMPERED;
  } else if (warnings.length > 0) {
    status = INTEGRITY_STATUS.CLOCK_SKEW_WARNING;
  }

  return {
    isValid,
    status,
    errors,
    warnings,
    checkedEntriesCount: entries.length,
    verifiedAt,
  };
}

/**
 * Factory to create an initial verifiable evidence bundle.
 *
 * @param {Object} complaint
 * @param {Object} [options]
 * @returns {Object} Fresh bundle manifest
 */
export function createInitialBundleManifest(complaint = {}, options = {}) {
  const timestamp = options.timestamp || new Date().toISOString();
  const bundleId = `VEB-${Date.now()}-${Math.floor(1000 + Math.random() * 9000)}`;

  return {
    schemaVersion: BUNDLE_SCHEMA_VERSION,
    bundleId,
    complaintId: complaint.id || `GRV-${Date.now()}`,
    complaintTitle: (complaint.title || 'Untitled Civic Complaint').trim(),
    department: (complaint.department || 'Municipal Administration').trim(),
    officialReferenceNumbers: Array.isArray(complaint.officialReferenceNumbers)
      ? complaint.officialReferenceNumbers.filter(Boolean)
      : [],
    createdAt: timestamp,
    updatedAt: timestamp,
    clockSkewToleranceMs: options.clockSkewToleranceMs || BUNDLE_CONSTRAINTS.DEFAULT_CLOCK_SKEW_TOLERANCE_MS,
    chainState: {
      entryCount: 0,
      rootHash: GENESIS_PREV_HASH,
      latestEntryHash: GENESIS_PREV_HASH,
      manifestSeal: '',
    },
    entries: [],
  };
}
